HERE="$(cd "$(dirname "$0")" && pwd)"
export LD_LIBRARY_PATH="${HERE}${LD_LIBRARY_PATH:+:${LD_LIBRARY_PATH}}"
exec "${HERE}/pono.bin" "$@"
EOF
chmod +x "$DEST/deps/pono" "$DEST/deps/pono.bin" "$DEST/deps/btormc" "$DEST/deps/catbtor" "$DEST/deps/ric3"

for name in avr avr.py avr_pr.py avr.sh workers.txt LICENSE README.md; do
