cat > "$DEST/README" << 'EOF'
MoXI-MC-Flow (SV-COMP 2027)
===========================

This archive is the SV-COMP 2027 tool submission of MoXI-MC-Flow. The tool
translates a native MoXI transition system to BTOR2 and checks the single
unsat-query with a portfolio of rIC3 (IC3 and k-induction), AVR (IC3), and
Pono (IC3). The first backend that finishes determines the result. Violation
witnesses are native MoXI check-system responses.

Project page: https://www.aere.iastate.edu/modelchecker/
Source:       https://github.com/ModelChecker/moxi-mc-flow
Version:      svcomp27

Contents
--------

LICENSE           GPL-3.0 text plus notes on bundled third-party binaries
README            this file
smoketest.sh      runs --version and three small MoXI examples
modelcheck.py     entry point used by BenchExec (benchexec.tools.moxi-mc-flow)
translate.py      MoXI/SMV/VMT/JSON to BTOR2 translator
sortcheck.py      MoXI sort checker
src/              Python implementation, including the PANDA binary used for SMV LTLSPECs
json-schema/      JSON dialect schema used by the translator
examples/         small QF_BV and QF_ABV MoXI files used by smoketest.sh
licenses/         licenses of bundled backends
deps/btormc       BtorMC binary
deps/catbtor      btor2tools checker used during translation
deps/ric3         rIC3 binary
deps/pono         wrapper that runs deps/pono.bin with deps/libpono.so
deps/avr/         AVR runtime (Python front-end plus statically linked workers)

The archive does not contain backend source trees, git metadata, tests, or
benchmarks.

Requirements
------------

- Python 3.11 or later
- python3-jsonschema
- libgmp10 (used by Pono)

On Ubuntu these are the packages `python3`, `python3-jsonschema`, and
`libgmp10`. The tool is executable from any working directory; paths are
resolved relative to this archive, not the current directory.

How to run
----------

The BenchExec tool-info module invokes:

    python3 modelcheck.py <input.moxi> [--timeout <seconds>]

With no extra solver argument, modelcheck.py runs a hard-coded portfolio
(rIC3, AVR, and Pono) on all available CPU cores. `--version` prints
`svcomp27`.

    python3 modelcheck.py --version
    python3 modelcheck.py examples/sat-qf_bv.moxi --timeout 60

Stdout contains a line starting with `sat` (property violated) or `unsat`
(property holds). A MoXI check-system response is written next to the input
as `<input>.witness` unless `--output` is given.

Smoke test
----------

From this directory:

    ./smoketest.sh

The script must exit 0. It checks `--version` and the three examples under
examples/.
EOF

cat > "$DEST/smoketest.sh" << 'EOF'
#!/bin/bash
# This file was generated by Cursor AI on 2026-10-20.
# SV-COMP 2027 smoke test for MoXI-MC-Flow. Exit 0 on success.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")" && pwd)"
MC=(python3 "$ROOT/modelcheck.py")
TIMEOUT=90

expect_version="$("${MC[@]}" --version 2>/dev/null | tr -d '[:space:]')"
if [[ "$expect_version" != "svcomp27" ]]; then
    echo "unexpected --version output: ${expect_version}" >&2
    exit 1
fi

run_example() {
    local input="$1"
    local expected="$2"
    local work
    work="$(mktemp -d)"
    trap 'rm -rf "$work"' RETURN
    local copy="$work/$(basename "$input")"
    cp "$input" "$copy"
    local output
    output="$(
        python3 "$ROOT/modelcheck.py" "$copy" --timeout "$TIMEOUT" --overwrite --quiet
    )"
    if ! grep -q "^${expected}" <<<"$output"; then
        echo "expected a line starting with '${expected}' for ${input}" >&2
        echo "stdout was:" >&2
        echo "$output" >&2
        exit 1
    fi
    echo "ok ${expected} $(basename "$input")"
}

# Run from a directory other than the tool directory.
cd /tmp
run_example "$ROOT/examples/sat-qf_bv.moxi" "sat"
run_example "$ROOT/examples/unsat-qf_bv.moxi" "unsat"
run_example "$ROOT/examples/sat-qf_abv.moxi" "sat"

echo "smoketest passed"
EOF
chmod +x "$DEST/smoketest.sh"

