        exit 1
    fi
done

STAGE="$(mktemp -d)"
trap 'rm -rf "$STAGE"' EXIT
mkdir -p "$STAGE/$INNER"
# Copy contents, not the svcomp27 directory name, so the ZIP has moxi-mc-flow/.
cp -a "$DEST"/. "$STAGE/$INNER/"
rm -f "$ZIP"
(
    cd "$STAGE"
    zip -qr "$ZIP" "$INNER" \
        -x '*/__pycache__/*' \
        -x '*.pyc' \
        -x '*/.git/*' \
        -x '*/.DS_Store'
)

echo "assembled $DEST"
echo "wrote $ZIP"
unzip -l "$ZIP" | head || true
echo "..."
unzip -l "$ZIP" | tail || true
python3 - "$ZIP" << 'PY'
import zipfile, sys
from pathlib import Path
z = zipfile.ZipFile(Path(sys.argv[1]))
names = z.namelist()
tops = sorted({n.split("/", 1)[0] for n in names if n})
assert len(tops) == 1, tops
root = tops[0]
for required in ("LICENSE", "README", "smoketest.sh"):
    assert f"{root}/{required}" in names, required
print(f"zip ok: single directory {root!r}, {len(names)} entries")
PY
